param()
$ErrorActionPreference='Stop';$root=$PSScriptRoot;$input=Join-Path $root 'input';New-Item -ItemType Directory -Force -Path $input | Out-Null
Add-Type -AssemblyName System.IO.Compression
function Write-ZipText($path,$entries){if(Test-Path $path){Remove-Item $path -Force};$fs=[IO.File]::Open($path,[IO.FileMode]::Create);$zip=[IO.Compression.ZipArchive]::new($fs,[IO.Compression.ZipArchiveMode]::Create);foreach($key in $entries.Keys){$e=$zip.CreateEntry($key);$sw=[IO.StreamWriter]::new($e.Open(),[Text.UTF8Encoding]::new($false));$sw.Write([string]$entries[$key]);$sw.Dispose()};$zip.Dispose();$fs.Dispose()}
$doc='<?xml version="1.0" encoding="UTF-8" standalone="yes"?><w:document xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main"><w:body><w:p><w:pPr><w:jc w:val="center"/></w:pPr><w:r><w:rPr><w:b/><w:sz w:val="36"/></w:rPr><w:t>Certificate of Completion</w:t></w:r></w:p><w:p><w:r><w:t>This certificate is proudly presented to</w:t></w:r></w:p><w:p><w:r><w:rPr><w:b/><w:sz w:val="28"/></w:rPr><w:t>{{STUDENT_NAME}}</w:t></w:r></w:p><w:p><w:r><w:t>for completing {{COURSE_NAME}}</w:t></w:r></w:p><w:p><w:r><w:t>Completion date: {{COMPLETION_DATE}}</w:t></w:r></w:p><w:sectPr><w:pgSz w:w="12240" w:h="15840"/><w:pgMar w:top="1440" w:right="1440" w:bottom="1440" w:left="1440"/></w:sectPr></w:body></w:document>'
$entries=[ordered]@{};$entries['[Content_Types].xml']='<?xml version="1.0" encoding="UTF-8"?><Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types"><Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/><Default Extension="xml" ContentType="application/xml"/><Override PartName="/word/document.xml" ContentType="application/vnd.openxmlformats-officedocument.wordprocessingml.document.main+xml"/></Types>';$entries['_rels/.rels']='<?xml version="1.0" encoding="UTF-8"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="word/document.xml"/></Relationships>';$entries['word/document.xml']=$doc;Write-ZipText (Join-Path $input 'CertificateTemplate.docx') $entries;Write-Output 'Initialized CertificateTemplate.docx'
